#!/usr/bin/env node
/**
 * Embed every template file into a TypeScript module.
 *
 * `packages/templates/files` is the one source of everything `delphi init` writes
 * (PACKAGING_SPEC section 1). It has to reach three distributions, and only one mechanism
 * works for all of them: a compiled binary has no template directory to read from, so
 * reading at runtime is out, and copying files into `dist` only helps the npm build.
 * Inlining them as strings works everywhere and makes "the templates are embedded" a thing
 * a test can check.
 *
 * The generated file is committed, and CI fails when it is stale — the same guarantee
 * PACKAGING_SPEC asks for around the generated plugin.
 *
 * It also mirrors the skills to a top-level `skills/` directory, because that is where
 * `npx skills add <owner>/<repo>` looks (vercel-labs/skills). Generating it from the same
 * source is the only way the two cannot drift: an edit to one without the other fails CI.
 *
 * Usage: node scripts/build-templates.mjs [--check]
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, posix, relative, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const source = join(root, 'packages/templates/files')
const target = join(root, 'packages/core/src/templates/files.generated.ts')
const check = process.argv.includes('--check')

/** Every file under `dir`, as paths relative to it, with forward slashes, sorted. */
function walk(dir) {
  const out = []
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry)
    if (statSync(full).isDirectory()) out.push(...walk(full))
    else out.push(full)
  }
  return out.sort()
}

const files = walk(source)
if (files.length === 0) throw new Error(`no templates found under ${source}`)

const entries = files.map((file) => {
  const key = relative(source, file).split(sep).join(posix.sep)
  // Normalise line endings so the generated file is identical on every platform, and so
  // a Windows checkout does not produce a diff CI then fails on.
  const content = readFileSync(file, 'utf8').replace(/\r\n/g, '\n')
  return `  ${JSON.stringify(key)}: ${JSON.stringify(content)},`
})

const generated = `// GENERATED by scripts/build-templates.mjs — do not edit.
// Source: packages/templates/files. Run \`pnpm build:templates\` after changing a template.

/** Every shipped template, keyed by its path relative to packages/templates/files. */
export const TEMPLATE_FILES: Readonly<Record<string, string>> = Object.freeze({
${entries.join('\n')}
})
`

/**
 * The skills, mirrored where `npx skills` looks for them.
 *
 * That CLI installs into Claude Code, Codex, Cursor and 75 other agents, and lets the user
 * choose project or global scope — none of which delphi has to implement, as long as the
 * files are where it expects. Returns the files it would write, so `--check` can compare
 * without touching the disk.
 */
function mirroredSkills() {
  const out = new Map()
  for (const file of files) {
    const key = relative(source, file).split(sep).join(posix.sep)
    if (!key.startsWith('skills/')) continue
    out.set(join(root, key), readFileSync(file, 'utf8').replace(/\r\n/g, '\n'))
  }
  return out
}

const skills = mirroredSkills()

if (check) {
  for (const [path, content] of skills) {
    let current = ''
    try {
      current = readFileSync(path, 'utf8').replace(/\r\n/g, '\n')
    } catch {
      console.error(`build-templates: ${relative(root, path)} is missing. Run: pnpm build:templates`)
      process.exit(1)
    }
    if (current !== content) {
      console.error(`build-templates: ${relative(root, path)} is stale. Run: pnpm build:templates`)
      process.exit(1)
    }
  }

  let current = ''
  try {
    current = readFileSync(target, 'utf8').replace(/\r\n/g, '\n')
  } catch {
    console.error(`build-templates: ${target} is missing. Run: pnpm build:templates`)
    process.exit(1)
  }
  if (current !== generated) {
    console.error('build-templates: the generated template module is stale. Run: pnpm build:templates')
    process.exit(1)
  }
  console.log(`build-templates: up to date (${files.length} templates)`)
} else {
  writeFileSync(target, generated)

  // Rewritten wholesale so a renamed or removed skill does not linger in the mirror.
  rmSync(join(root, 'skills'), { recursive: true, force: true })
  for (const [path, content] of skills) {
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, content)
  }

  const bytes = generated.length
  console.log(
    `build-templates: embedded ${files.length} templates (${Math.round(bytes / 1024)} KB), ` +
      `mirrored ${skills.size} skills to skills/`,
  )
}
